export function add(a, b) { return a + b; }

export function sub(a, b) { return a - b; }

export function mul(a, b) { return a * b; }

export function div(a, b) {
  if (b === 0) {
    throw new Error('Division by zero');
  }
  return a / b;
}

import { test } from 'node:test';
import assert from 'node:assert/strict';

import { add, sub, mul, div } from '../src/app.js';

test('add returns the sum of two numbers', () => {
  assert.equal(add(2, 3), 5);
  assert.equal(add(-1, 1), 0);
});

test('sub returns the difference of two numbers', () => {
  assert.equal(sub(5, 3), 2);
  assert.equal(sub(3, 5), -2);
});

test('mul returns the product of two numbers', () => {
  assert.equal(mul(4, 3), 12);
  assert.equal(mul(-2, 3), -6);
});

test('div returns the quotient of two numbers', () => {
  assert.equal(div(10, 2), 5);
  assert.equal(div(1, 4), 0.25);
});

test('div throws when dividing by zero', () => {
  assert.throws(() => div(1, 0), /Division by zero/);
});

